'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',file:'<path d="M14 2H5a1 1 0 0 0-1 1v18a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1V8z"/><path d="M14 2v6h6M8 13h8M8 17h5"/>',book:'<path d="M3 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H3zm18 0h-6a3 3 0 0 0-3 3v14a4 4 0 0 1 4-2h5z"/>',spark:'<path d="m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6zM20 2v4M18 4h4"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M21 21v-2a6 6 0 0 0-4-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2M14 15h2"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',logout:'<path d="M9 3H4v18h5M9 12h12m-5-5 5 5-5 5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',send:'<path d="m22 2-7 20-4-9L2 9zM11 13 22 2"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6z"/><path d="m8 12 3 3 5-6"/>'};
Object.assign(icons,{search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/>'});
const icon=n=>`<svg class="svg" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const roles={employee:'Сотрудник',manager:'Руководитель',hr:'HR / администратор'};
const labels={submitted:'На согласовании',approved:'Согласована руководителем',completed:'Обработана HR',rejected:'Отклонена',withdrawn:'Отозвана'};
const state={user:null,csrf:'',page:'home',requests:[],courses:[],notifications:[],documents:[],team:[],filter:'all',messages:[],course:null,busy:false,theme:localStorage.getItem('jana-theme')||'auto',search:'',navigating:false,revision:'',assistantMode:'extractive',teamFilter:'action',teamSearch:''};
const initials=n=>n.split(' ').slice(0,2).map(x=>x[0]).join('');
const kkMonths=['қаңтар','ақпан','наурыз','сәуір','мамыр','маусым','шілде','тамыз','қыркүйек','қазан','қараша','желтоқсан'];
const kkDays=['жексенбі','дүйсенбі','сейсенбі','сәрсенбі','бейсенбі','жұма','сенбі'];
const dateValue=s=>new Date(s.length===10?s+'T12:00:00':s);
const date=s=>{const d=dateValue(s);return window.JanaI18n?.lang==='kk'?`${d.getDate()} ${kkMonths[d.getMonth()]} ${d.getFullYear()} ж.`:d.toLocaleDateString(({uz:'uz-UZ',tg:'tg-TJ',mn:'mn-MN',ky:'ky-KG',en:'en-GB'})[window.JanaI18n?.lang]||'ru-RU',{day:'numeric',month:'short',year:'numeric'});};
const shortDate=s=>{const d=dateValue(s);return window.JanaI18n?.lang==='kk'?`${d.getDate()} ${kkMonths[d.getMonth()]}`:d.toLocaleDateString('ru-RU',{day:'numeric',month:'short'});};
const todayLabel=()=>{const d=new Date();return window.JanaI18n?.lang==='kk'?`${kkDays[d.getDay()]}, ${d.getDate()} ${kkMonths[d.getMonth()]}`:d.toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'});};
const range=r=>`${shortDate(r.start_date)} — ${shortDate(r.end_date)}`;
const days=r=>Math.round((new Date(r.end_date)-new Date(r.start_date))/86400000)+1;
const plural=(n,one,few,many)=>n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&!(n%100>=12&&n%100<=14)?few:many;
const calendarDays=n=>`${n} ${plural(n,'календарный день','календарных дня','календарных дней')}`;
const pill=r=>`<span class="pill ${esc(r.status)}">${esc(labels[r.status])}</span>`;
const progress=c=>c.completed?100:c.lesson_done?50:0;
const empty=(title,text)=>`<div class="empty">${icon('file')}<h3>${esc(title)}</h3><p>${esc(text)}</p></div>`;
function toast(text){$('#toast').innerHTML=icon('check')+'<span>'+esc(text)+'</span>';$('#toast').setAttribute('aria-live','polite');$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
async function api(path,data){
 if(!navigator.onLine)throw new Error('Нет соединения. Действие не отправлено.');
 const controller=new AbortController();let timedOut=false;
 const timer=setTimeout(()=>{timedOut=true;controller.abort();},path==='assistant'?65000:25000);
 const opts={headers:{},signal:controller.signal,cache:'no-store',credentials:'same-origin'};
 if(data!==undefined){opts.method='POST';opts.headers={'Content-Type':'application/json','X-CSRF-Token':state.csrf};opts.body=JSON.stringify(data);}
 try{const response=await fetch('/api/'+path,opts);let body;
 try{body=await response.json();}catch{throw new Error('Сервер вернул непонятный ответ. Проверьте адрес и соединение.');}
 if(!response.ok){if(response.status===401&&state.user){state.user=null;renderLogin();}throw new Error(body.error||'Ошибка запроса');}return body;
 }catch(e){if(timedOut)throw new DOMException('Ожидание ответа истекло. Проверьте историю перед повторной отправкой.','TimeoutError');if(e instanceof TypeError)throw new Error('Связь с сервером потеряна. Если отправляли действие, проверьте его статус после подключения, прежде чем повторять.');throw e;
 }finally{clearTimeout(timer);}
}
function modal(title,body){const d=$('#modal');delete d.dataset.requestId;delete d.dataset.readStatus;d.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div><div class="modal-body">${body}</div>`;d.setAttribute('aria-labelledby','dialog-title');if(!d.open)d.showModal();d.scrollTop=0;localize();}
function modalError(message){let e=$('#modal .error');if(!e){e=document.createElement('div');e.className='error';e.setAttribute('role','alert');$('.modal-body').prepend(e);}e.textContent=message;$('#modal').scrollTop=0;}
const logo=()=>`<div class="logo"><img src="/assets/jana-logo.svg" alt="Jańa Post" width="77" height="40"><span class="logo-divider"></span><span class="product-name">JanaМен<small>пространство сотрудника</small></span></div>`;
let navigation=()=>[['home','home','Обзор'],['requests','file','Мои заявки'],...(state.user?.role!=='employee'?[['team','users',state.user?.role==='hr'?'HR-кабинет':'Моя команда']]:[]),['academy','book','Academy'],['assistant','spark','AI Jana'],['notifications','bell','Уведомления']];
function themeLabel(){return {auto:'Системная',light:'Светлая',dark:'Тёмная'}[state.theme];}
function applyTheme(){document.documentElement.dataset.theme=state.theme;localStorage.setItem('jana-theme',state.theme);}
applyTheme();
function renderLogin(){stopSync();for(const key of Object.keys(sessionStorage))if(key.startsWith('jana-draft-'))sessionStorage.removeItem(key);state.threadId=null;state.messages=[];state.extra={};state.requests=[];state.notifications=[];state.documents=[];state.team=[];$('#app').innerHTML=`<main class="login-page"><header class="login-header">${logo()}<div class="login-tools"><button class="btn" data-action="language">RU / KZ</button><span class="pill neutral">Команда 45 · Digital HR</span></div></header><div class="login-heading"><span class="eyebrow">Люди — в центре. Всё остальное — рядом.</span><h1>Доставляем возможности.<br><span>Теперь и в твоей работе.</span></h1><p>Единое пространство для команды Jana Post.</p></div><div class="login-grid"><section class="login-visual"><div class="visual-topline"><span class="light-chip">JanaМен / Employee experience</span>${icon('spark')}</div><h2>Меньше поиска.<br>Больше движения<br>вперёд.</h2><p>Одна точка входа для заявок, знаний<br>и твоего развития.</p><div class="login-route" aria-label="Путь заявки: сотрудник, руководитель, HR"><div><span>${icon('file')}</span><strong>Твоя заявка</strong><small>Пара понятных шагов</small></div><i></i><div><span>${icon('users')}</span><strong>Решение</strong><small>Прозрачный маршрут</small></div><i></i><div><span>${icon('check')}</span><strong>Результат</strong><small>История и уведомление</small></div></div><div class="visual-bottom"><span>Открытость</span><span>Надёжность</span><span>Результат</span></div></section><section class="login-panel"><form id="login-form" class="login-form"><span class="eyebrow">Добро пожаловать</span><h2>Твой рабочий кабинет</h2><p>Войди, чтобы продолжить.</p><div id="login-error" class="error hidden" role="alert"></div><div class="form-field"><label for="email">Электронная почта</label><input id="email" name="email" type="email" autocomplete="username"  required></div><div class="form-field"><label for="password">Пароль</label><div class="password-field"><input id="password" name="password" type="password" autocomplete="current-password" required><button type="button" class="password-toggle" data-action="toggle-password" aria-label="Показать пароль">${icon('eye')}</button></div></div><button class="btn primary login-submit" type="submit">Войти в JanaМен ${icon('arrow')}</button><details class="login-help"><summary>Нет доступа или забыли пароль?</summary><p>Аккаунты создаёт HR вашей компании. Для восстановления доступа обратитесь в HR: вам выдадут временный пароль с обязательной сменой.</p></details><div class="login-footer">${icon('lock')} Доступ только для сотрудников</div></form></section></div><footer class="login-disclaimer">Неофициальный учебный прототип по кейсу Jana Post × Terricon Valley. Только синтетические данные.</footer></main>`;window.scrollTo(0,0);localize();}
async function load(){const me=await api('me');state.assistantMode=me.assistant_mode;state.aiStatus=me.ai_status;const [data,k]=await Promise.all([api('snapshot'),api('knowledge')]);applySnapshot(data);state.documents=k.documents;if(state.user.role!=='employee')state.team=(await api('team')).users;}
function applySnapshot(data){state.user=data.user;state.requests=data.requests;state.courses=data.courses;state.notifications=data.notifications;state.revision=data.revision;state.extra=data.extra||{};}

function shell(){const u=state.user;const unread=state.notifications.filter(x=>!x.is_read).length;const nav=navigation();$('#app').innerHTML=`<div class="layout"><div class="utility-bar"><span>${icon('shield')} Командное пространство <span class="utility-dot"></span> Единая рабочая среда</span><div><button data-action="theme" class="utility-button" aria-label="Сменить тему: ${themeLabel()}">${icon('sun')} <span>${themeLabel()}</span></button><button class="utility-button utility-language" data-action="language">RU / KZ</button><button class="utility-button" data-action="logout">${icon('logout')} Выйти</button></div></div><header class="site-header"><div class="header-main"><button class="brand-button" data-page="home" aria-label="На главную">${logo()}</button><div class="header-actions"><button class="search-trigger" data-action="command">${icon('search')}<span>Найти в JanaМен</span><kbd>Ctrl K</kbd></button><button class="notification-trigger icon-btn" data-page="notifications" aria-label="Уведомления: ${unread} непрочитанных">${icon('bell')}${unread?'<i class="notification-dot"></i>':''}</button><button class="user-button" data-action="profile" aria-label="Открыть профиль"><span class="avatar">${esc(initials(u.name))}</span><span class="userline"><strong>${esc(u.name)}</strong><small>${esc(roles[u.role])}</small></span></button><button class="icon-btn menu-btn" data-action="menu" aria-label="Открыть меню" aria-expanded="false">${icon('menu')}</button></div></div><nav class="nav desktop-nav" aria-label="Главное меню">${nav.map(([p,i,t])=>`<button data-page="${p}" class="${state.page===p?'active':''}" ${state.page===p?'aria-current="page"':''}>${icon(i)}${t}${p==='notifications'&&unread?`<span class="count">${unread}</span>`:''}</button>`).join('')}<span class="nav-end" id="sync-status" role="status">Проверяю соединение…</span></nav></header><button class="mobile-shade" data-action="menu" aria-label="Закрыть меню"></button><aside class="sidebar" aria-label="Мобильное меню"><div class="drawer-head">${logo()}<button class="icon-btn" data-action="menu" aria-label="Закрыть меню">${icon('close')}</button></div><nav class="nav">${nav.map(([p,i,t])=>`<button data-page="${p}" class="${state.page===p?'active':''}">${icon(i)}${t}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="drawer-tools"><button class="btn" data-action="profile">Мой профиль</button><button class="btn" data-action="language">RU / KZ</button></div><div class="demo-box"><strong>JanaМен</strong>Рабочие задачи, документы и сервисы — рядом.</div><button class="btn ghost section-gap" data-action="logout">${icon('logout')} Выйти из аккаунта</button></div></aside><div id="connection-banner" class="connection-banner hidden" role="status"></div><main class="content" id="content"></main><footer class="site-footer"><span>JanaМен <b>·</b> Люди. Знания. Возможности.</span><span>${icon('lock')} Команда 45 · Digital HR</span></footer><div id="navigation-progress" aria-hidden="true"></div></div>`;renderPage();window.scrollTo(0,0);localize();startSync();}

function head(title,sub,button=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${button}</div>`;}
function renderPage(){const f={...(window.extraPages||{}),home:homePage,requests:requestsPage,academy:academyPage,team:teamPage,assistant:assistantPage,notifications:notificationsPage};const content=$('#content');if(!content)return;content.innerHTML=(f[state.page]||homePage)();content.classList.remove('page-enter');void content.offsetWidth;content.classList.add('page-enter');animateProgress(content);localize();}

function requestRow(r){return `<div class="request-row" role="button" tabindex="0" data-request="${r.id}" aria-label="Открыть заявку ${r.id}"><div class="row-icon">${icon('calendar')}</div><div class="grow"><div class="row-title">Отпуск · ${days(r)} дн.</div><div class="row-sub">${esc(range(r))} · №${r.id}</div></div>${pill(r)}</div>`;}
function homePage(){const u=state.user,mine=state.requests.filter(r=>r.user_id===u.id),assigned=state.courses.filter(c=>c.lesson_done!==null),active=mine.filter(r=>['submitted','approved'].includes(r.status));const dateLabel=todayLabel();const tracked=active[0]||mine[0],course=assigned.find(c=>!c.completed);const completed=assigned.filter(c=>c.completed).length;return `<div class="page-head dashboard-heading"><div><div class="greeting-date">${esc(dateLabel)} <span class="tiny-dot"></span> ${esc(u.department)}</div><h1>Привет, ${esc(u.name.split(' ')[0])}<span class="greeting-dot">.</span></h1><p>Хороший день начинается с простых вещей.</p></div><button class="btn primary" data-action="new-request">${icon('plus')} Заявка на отпуск</button></div><div class="dashboard-hero"><section class="hero-copy"><span class="eyebrow">Твой день. Твои возможности.</span><h2>Работа — в движении.<br><span>Всё важное — под рукой.</span></h2><p>Заявки, развитие и ответы HR.<br>Без лишних вкладок и ожидания в чатах.</p><div class="hero-actions"><button class="btn primary" data-page="assistant">Спросить AI Jana ${icon('arrow')}</button><button class="btn ghost" data-page="academy">К обучению ${icon('book')}</button></div><div class="hero-caption">${icon('shield')} Единый кабинет · доступ по твоей роли</div></section><section class="journey-card"><div class="journey-card-top"><span class="light-chip">${tracked?'Маршрут твоей заявки':'Твой следующий шаг'}</span>${icon('arrow')}</div>${tracked?`<h3>Отпуск №${tracked.id}</h3><p>${esc(range(tracked))} · ${calendarDays(days(tracked))}</p><div class="route-track" data-stage="${tracked.status}">${[['submitted','Отправлено'],['approved','Руководитель'],['completed','HR']].map(([stage,label],i)=>{const reached=tracked.history.some(h=>h.status===stage);return `<div class="route-stop ${reached?'done':''}"><span>${reached?icon('check'):String(i+1).padStart(2,'0')}</span><strong>${label}</strong></div>`;}).join('')}</div><div class="journey-card-bottom"><span class="route-status">${icon(tracked.status==='completed'?'check':'clock')} ${esc(labels[tracked.status])}</span><button class="route-detail" data-request="${tracked.id}" aria-label="Открыть маршрут заявки ${tracked.id}">${icon('arrow')}</button></div>`:`<h3>Одна заявка.<br>Прозрачный путь.</h3><p>Сотрудник → руководитель → HR.<br>Каждый шаг сохраняется в истории.</p><button class="btn white-btn section-gap" data-action="new-request">Создать заявку ${icon('arrow')}</button>`}</section></div><div class="grid stats"><button class="stat" data-page="requests"><div class="stat-label">${icon('calendar')} Дни для перезагрузки</div><div class="stat-value">${u.vacation_days}<span>дня отпуска</span></div><div class="stat-bottom"><span>Тестовый кадровый баланс</span>${icon('arrow')}</div></button><button class="stat" data-page="requests"><div class="stat-label">${icon('file')} Под твоим контролем</div><div class="stat-value">${active.length.toString().padStart(2,'0')}<span>заявок в работе</span></div><div class="stat-bottom"><span>История и актуальные статусы</span>${icon('arrow')}</div></button><button class="stat stat-accent" data-page="academy"><div class="stat-label">${icon('book')} Следующий уровень</div><div class="stat-value">${assigned.filter(c=>!c.completed).length.toString().padStart(2,'0')}<span>курсов впереди</span></div><div class="stat-bottom"><span>${completed} завершено · Jana Academy</span>${icon('arrow')}</div></button></div><div class="grid two-col"><div class="stack"><section class="card"><div class="card-head"><div><span class="section-kicker">От идеи к решению</span><h2>Мои заявки</h2></div><button class="btn ghost" data-page="requests">Все заявки ${icon('arrow')}</button></div>${mine.length?mine.slice(0,3).map(requestRow).join(''):empty('Пока нет заявок','Создай первую заявку на отпуск.')}</section><section class="card academy-feature"><div class="card-head"><div><span class="section-kicker">Расти вместе с командой</span><h2>Jana Academy</h2></div><span class="pill neutral">${assigned.length} назначено</span></div>${course?`<div class="featured-course"><div class="featured-course-icon">${icon('book')}</div><div class="grow"><span class="small muted">${course.duration} минут · материал и тест</span><h3>${esc(course.title)}</h3><p class="small muted">${esc(course.description)}</p><div class="progress" data-value="${progress(course)}" role="progressbar" aria-label="Прогресс курса" aria-valuenow="${progress(course)}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill"></div></div><div class="course-progress-caption"><span>${progress(course)}% пройдено</span><span>${course.lesson_done?'Остался тест':'Можно начать сейчас'}</span></div><button class="btn primary section-gap" data-course="${course.id}">${course.lesson_done?'Продолжить обучение':'Начать обучение'} ${icon('arrow')}</button></div></div>`:empty('Отличная работа','Нет незавершённых назначенных курсов.')}</section></div><aside class="stack"><section class="card profile-card"><div class="card-head"><h2>Мой профиль</h2><span class="icon-label" title="Только для чтения">${icon('lock')}</span></div><div class="card-pad"><div class="profile-top"><div class="avatar">${esc(initials(u.name))}</div><div><h3>${esc(u.name)}</h3><span class="small muted">${esc(u.position)}</span></div></div><div class="fields">${[['Компания',u.company],['Подразделение',u.department],['Руководитель',u.manager_name],['В команде с',date(u.hire_date)]].map(([k,v])=>`<div><span class="field-key">${k}</span><span class="field-value">${esc(v)}</span></div>`).join('')}</div><div class="readonly">${icon('info')}<span>Нужны изменения? Обратись в HR. Кадровые поля доступны только для чтения.</span></div></div></section><section class="help-card"><span class="help-icon">${icon('spark')}</span><div><h3>Нужен быстрый ответ?</h3><p>Помощник найдёт источник.<br>Не найдёт — честно скажет.</p></div><button class="icon-btn" data-page="assistant" aria-label="Открыть помощника">${icon('arrow')}</button></section></aside></div>`;}

function requestTable(rows,team=false){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Заявка</th>${team?'<th>Сотрудник</th>':''}<th>Период</th><th>Статус</th><th><span class="muted">Детали</span></th></tr></thead><tbody>${rows.map(r=>`<tr><td data-label="Заявка"><div><strong>Отпуск №${r.id}</strong><div class="row-sub">Создана ${esc(date(r.created_at))}</div></div></td>${team?`<td data-label="Сотрудник">${esc(r.name)}</td>`:''}<td data-label="Период"><div>${esc(range(r))}<div class="row-sub">${calendarDays(days(r))}</div></div></td><td data-label="Статус"><div>${pill(r)}</div></td><td data-label="Детали"><button class="icon-btn table-action" data-request="${r.id}" aria-label="Открыть заявку ${r.id}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Заявок пока нет','Здесь появятся заявки с выбранным статусом.');}
function requestsPage(){let rows=state.requests.filter(r=>r.user_id===state.user.id);if(state.filter!=='all')rows=rows.filter(r=>r.status===state.filter);return head('Мои заявки','История обращений и решения — всегда под рукой.',`<button class="btn primary" data-action="new-request">${icon('plus')} Новая заявка</button>`)+`<div class="filters" aria-label="Фильтр по статусу">${[['all','Все'],['submitted','На согласовании'],['approved','Согласованы'],['completed','Обработаны'],['rejected','Отклонены'],['withdrawn','Отозваны']].map(([v,t])=>`<button class="filter ${state.filter===v?'active':''}" data-filter="${v}" aria-pressed="${state.filter===v}">${t}</button>`).join('')}</div><div class="card">${requestTable(rows)}</div><div class="info-strip">${icon('info')}<span>В MVP доступен отпуск. Остаток не списывается автоматически: будущий источник официального баланса — 1С:ЗУП.</span></div>`;}
function teamPage(){if(state.user.role==='employee')return empty('Нет доступа','Раздел доступен руководителю и HR.');const isHR=state.user.role==='hr',rows=state.requests.filter(r=>r.user_id!==state.user.id);return head(isHR?'HR-кабинет':'Моя команда',isHR?'Обработка согласованных заявок и назначение обучения.':'Только разрешённые данные твоей команды.',`<button class="btn" data-action="refresh">${icon('arrow')} Обновить</button>`)+`<section class="card"><div class="card-head"><h2>${isHR?'Заявки сотрудников':'Заявки команды'}</h2><span class="pill neutral">${rows.length}</span></div>${requestTable(rows,true)}</section><h2 class="section-gap">${isHR?'Сотрудники':'Прямые подчинённые'}</h2><div class="grid team-grid section-gap">${state.team.map(u=>`<section class="card card-pad team-card"><div class="profile-top"><div class="avatar">${esc(initials(u.name))}</div><div><h3>${esc(u.name)}</h3><span class="small muted">${esc(u.position)}</span></div></div><p class="small muted section-gap">${esc(u.department)} · ${esc(roles[u.role])}</p>${isHR?`<button class="btn" data-assign="${u.id}">${icon('book')} Назначить курс</button>`:''}</section>`).join('')}</div><div class="info-strip">${icon('shield')} Права проверяются сервером, а не только скрытием кнопок.</div>`;}
function academyPage(){return head('Jana Academy','Новые знания — в твоём темпе.')+`<div class="grid course-grid">${state.courses.map(c=>`<section class="card course-card"><div class="course-symbol">${icon(c.id===1?'book':'shield')}</div><span class="pill ${c.lesson_done===null?'neutral':''}">${c.lesson_done===null?'Доступен для назначения':c.completed?'Завершён':'Назначен тебе'}</span><h2>${esc(c.title)}</h2><p class="muted">${esc(c.description)}</p><div class="course-meta">${icon('clock')} ${c.duration} минут <span>·</span> Материал + тест</div>${c.lesson_done!==null?`<div class="progress" data-value="${progress(c)}" role="progressbar" aria-label="Прогресс курса" aria-valuenow="${progress(c)}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill"></div></div><span class="small muted">${c.completed?'Результат: '+c.score+'%':progress(c)+'% пройдено'}</span><button class="btn ${c.completed?'':'primary'}" data-course="${c.id}">${c.completed?'Повторить материал':c.lesson_done?'Продолжить':'Открыть курс'} ${icon('arrow')}</button>`:'<p class="small muted">Попроси HR назначить этот курс.</p>'}</section>`).join('')}</div><div class="info-strip">${icon('info')} Материалы учебные: они демонстрируют платформу и не заменяют официальные инструкции компании.</div>`;}
function notificationsPage(){return head('Уведомления','Важное о заявках и обучении.',`<button class="btn" data-action="read-notifications">${icon('check')} Прочитать все</button>`)+`<section class="card">${state.notifications.length?state.notifications.map(n=>`<article class="notification ${n.is_read?'':'unread'}"><div class="row-icon">${icon(n.kind==='learning'?'book':'bell')}</div><div class="grow"><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><time datetime="${esc(n.created_at)}">${esc(date(n.created_at))}</time><button class="btn ghost" ${n.target_id?(n.kind==='learning'?`data-course="${n.target_id}"`:`data-request="${n.target_id}"`):`data-page="${n.kind==='learning'?'academy':state.user.role==='employee'?'requests':'team'}"`}>${n.kind==='learning'?'К обучению':state.user.role==='employee'?'К моим заявкам':'К заявкам команды'} ${icon('arrow')}</button></div>${!n.is_read?'<span class="dot" aria-label="Не прочитано"></span>':''}</article>`).join(''):empty('Всё спокойно','Здесь появятся изменения статусов и события обучения.')}</section>`;}
function assistantPage(){return head('AI Jana','Найти ответ. Проверить источник. Продолжить работу.')+`<div class="grid chat-layout"><section class="card chat-window"><div class="chat-intro"><div class="course-symbol">${icon('spark')}</div><h2>Чем помочь?</h2><p>Отпуск, профиль или обучение — начни с вопроса.</p><div class="suggestions">${['Как оформить отпуск?','Где посмотреть статус заявки?','Как пройти курс?'].map(q=>`<button class="btn" data-question="${q}">${q}</button>`).join('')}</div></div><div class="messages" id="messages" aria-live="polite">${renderMessages()}${state.busy?'<div class="assistant-thinking" role="status"><span></span><span></span><span></span> Жду ответ модели…</div>':''}</div><form id="chat-form" class="chat-input"><label class="hidden" for="question">Вопрос помощнику</label><textarea id="question" name="question" rows="1" maxlength="1000" placeholder="Напиши сообщение Jana…" required aria-label="Вопрос помощнику"></textarea><button class="btn primary" aria-label="Отправить вопрос" type="submit" ${state.busy?'disabled':''}>${icon('send')}<span class="send-label">Отправить</span></button></form><p class="assistant-note">Сборка 1.4 iPhone · Gemini. ${state.aiStatus?.resolved_model?`Модель: ${esc(state.aiStatus.resolved_model)}. `:""}${window.JanaI18n?.lang==='kk'?'Дереккөздер мен бейне орыс тілінде. ':''}${['groq','anymodel','gemini'].includes(state.assistantMode)?`Настроен ${state.assistantMode==='gemini'?'Google Gemini':state.assistantMode==='anymodel'?'AnyModel':'Groq'}. Обычный диалог с моделью. История этого чата и доступные инструкции передаются провайдеру. Не вводите пароли и персональные данные. Запросы по своему аккаунту обрабатываются локально.`:'Ключ ИИ не настроен. Добавьте ключ Google в GEMINI_KEY.txt на сервере. Свои данные можно проверить локально.'}</p></section><aside class="stack"><section class="card card-pad chat-knowledge"><h3>База знаний</h3><p class="small muted section-gap">Только доступные твоей роли учебные документы.</p>${state.documents.map(d=>`<button class="knowledge-button" data-document="${d.id}">${icon('file')}<span>${esc(d.title)}</span></button>`).join('')}</section><section class="card card-pad"><span class="pill neutral">Важное о данных</span><p class="small muted section-gap">ИИ может ошибаться. Кадровые правила проверяйте у HR. Закрытые записи коллег не передаются модели.</p></section></aside></div>`;}
function renderMessages(){return state.messages.map(m=>`<div class="message ${m.role==='user'?'user':''}"><span class="message-label">${m.role==='user'?'Ты':m.mode==='ollama'?'AI Jana · локальная модель':m.mode==='error'?'Jana · ошибка подключения':m.mode==='no_answer'?'Jana · нет источника':'Jana · выдержка из базы'}</span>${esc(m.text)}${m.sources?.length?`<div class="sources">${m.sources.map(s=>`<button class="btn" data-document="${s.id}">${icon('file')} ${esc(s.title)}</button>`).join('')}</div>`:''}${m.mode==='extractive_fallback'?'<p class="small muted section-gap">Локальная модель недоступна. Показан исходный текст документа.</p>':''}</div>`).join('');}
function newRequest(){const today=new Date();today.setMinutes(today.getMinutes()-today.getTimezoneOffset());modal('Новая заявка на отпуск',`<p class="modal-subtitle">Отпуск · календарные дни</p><form id="request-form"><div class="form-row"><div class="form-field"><label for="start">Дата начала</label><input type="date" id="start" name="start" min="${today.toISOString().slice(0,10)}" required></div><div class="form-field"><label for="end">Дата окончания</label><input type="date" id="end" name="end" min="${today.toISOString().slice(0,10)}" required></div></div><div id="leave-preview" class="leave-preview"><div class="leave-preview-icon">${icon('calendar')}</div><div><strong>Выбери даты отпуска</strong><p>Рассчитаем календарные дни перед отправкой.</p></div></div><div class="form-field"><label for="comment">Комментарий · необязательно</label><textarea id="comment" name="comment" rows="3" maxlength="1000" placeholder="Без реальных персональных данных"></textarea></div><div class="info-strip">${icon('info')}<span>Тестовый остаток: ${state.user.vacation_days} дня. Пересекающиеся заявки не допускаются. Отправка не означает согласование.</span></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Отмена</button><button type="submit" class="btn primary">Отправить заявку ${icon('arrow')}</button></div></form>`);}
function openRequest(id){const r=state.requests.find(x=>x.id===id);if(!r)return;const u=state.user,own=r.user_id===u.id;const manager=!own&&u.role==='manager'&&r.status==='submitted';const hr=!own&&u.role==='hr'&&['submitted','approved'].includes(r.status);modal(`Отпуск · заявка №${r.id}`,`<div class="modal-subtitle">${esc(r.name)} · создана ${esc(date(r.created_at))}</div>${pill(r)}${requestStepper(r)}<div class="details"><div><span class="field-key">Период</span><strong>${esc(range(r))}</strong></div><div><span class="field-key">Длительность</span><strong>${calendarDays(days(r))}</strong></div></div>${r.comment?`<div class="info-strip">${icon('file')}<span class="user-content">${esc(r.comment)}</span></div>`:''}<div class="next-step"><strong>Что происходит дальше?</strong><p>${r.status==='submitted'?'Руководитель рассматривает заявку. После согласования она поступит HR. Срок рассмотрения согласуется с HR.':r.status==='approved'?'Руководитель согласовал. Заявка ожидает завершения обработки HR.':r.status==='completed'?'Обработка в платформе завершена. Юридический документ в Documentolog не создавался.':r.status==='withdrawn'?'Сотрудник отозвал заявку до решения. При необходимости создайте новую заявку.':'Заявка отклонена. Причина указана в истории; можно оформить новую заявку с другими датами.'}</p></div><h3>История заявки</h3><div class="timeline">${r.history.map(h=>`<div class="timeline-item"><span class="timeline-step">${icon('check')}</span><div><strong>${esc(labels[h.status])}</strong><p>${esc(h.actor)} · ${esc(date(h.created_at))}</p><p>${esc(h.comment)}</p></div></div>`).join('')}</div>${manager||hr?`<form id="action-form" data-id="${r.id}" class="section-gap"><div class="form-field"><label for="decision-comment">Комментарий к решению</label><textarea id="decision-comment" name="comment" rows="2" maxlength="1000" placeholder="Обязателен при отклонении"></textarea></div><div class="modal-actions"><button class="btn danger" type="submit" name="decision" value="rejected">Отклонить</button>${manager?'<button class="btn primary" type="submit" name="decision" value="approved">Согласовать</button>':''}${hr&&r.status==='approved'?'<button class="btn primary" type="submit" name="decision" value="completed">Завершить обработку</button>':''}</div>${hr&&r.status==='submitted'?'<p class="small muted section-gap">Для завершения обработки требуется согласование руководителя.</p>':''}</form>`:''}`);}
async function openCourse(id){state.course=await api('course',{id});drawCourse();}
function drawCourse(result){const c=state.course,a=c.assignment;modal(c.title,`<p class="modal-subtitle">${c.duration} минут · учебный материал · ${a.completed?'завершён':a.lesson_done?'материал изучен':'в процессе'}</p>${c.id===1?tutorialVideo():''}${c.content.map((l,i)=>`<section class="lesson"><span class="eyebrow">${String(i+1).padStart(2,'0')} / Материал</span><h3 class="section-gap">${esc(l.title)}</h3><p>${esc(l.text)}</p></section>`).join('')}${result?`<div class="${result.passed?'success':'error'}" role="status">${result.passed?'Курс пройден!':'Попробуй ещё раз.'} Результат: ${result.score}%. Лучший: ${result.best_score}%.</div>`:''}${!a.lesson_done?`<button class="btn primary section-gap" data-action="lesson-done">${icon('check')} Материал изучен — перейти к тесту</button>`:`<form id="quiz-form" class="section-gap"><h3>Проверка знаний</h3><p class="small muted">Для завершения требуется не менее 67%. Можно повторить тест.</p>${c.questions.map((q,i)=>`<fieldset><legend>${i+1}. ${esc(q.text)}</legend>${q.options.map((o,j)=>`<label class="radio"><input type="radio" name="q${i}" value="${j}" required><span>${esc(o)}</span></label>`).join('')}</fieldset>`).join('')}<button class="btn primary" type="submit">Проверить ответы ${icon('arrow')}</button>${a.score!==null?`<p class="small muted section-gap">Лучший сохранённый результат: ${a.score}%</p>`:''}</form>`}`);if(result)$('#modal .success, #modal .error')?.scrollIntoView({block:'center'});}
function openAssign(uid){const u=state.team.find(x=>x.id===uid);modal('Назначить обучение',`<p class="modal-subtitle">Сотрудник: ${esc(u.name)}</p><form id="assign-form" data-user="${uid}"><div class="form-field"><label for="course-id">Курс</label><select id="course-id" name="course_id">${state.courses.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></div><div class="modal-actions"><button class="btn primary" type="submit">Назначить курс</button></div></form>`);}
async function ask(question){if(state.busy||!state.user)return;const owner=state.user.id;state.busy=true;state.messages.push({role:'user',text:question});renderPage();try{const a=await api('assistant',{question,lang:window.JanaI18n?.lang||'ru',thread_id:state.threadId||null,client_id:crypto.randomUUID()});if(!state.user||state.user.id!==owner)return;state.threadId=a.thread_id;if(a.provider_config){state.aiStatus=a.provider_config;state.assistantMode=a.provider_config.provider;}state.messages.push({role:'assistant',text:a.answer,sources:a.sources,mode:a.mode,claims:a.claims,notice:a.notice,actions:a.actions});}catch(e){if(state.user?.id===owner)state.messages.push({role:'assistant',text:e.name==='TimeoutError'?'Ответ не успел прийти. Откройте историю диалога перед повторной отправкой.':e.message,mode:'no_answer'});}finally{if(state.user?.id!==owner){state.busy=false;return;}if(state.threadId){try{state.extra.chat_threads=(await api('chat/list')).threads;}catch{}}state.busy=false;renderPage();$('#question')?.focus({preventScroll:true});}}
async function refresh(){await load();shell();}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-request]');if(!b)return;try{if(b.dataset.page){await navigate(b.dataset.page);return;}if(b.dataset.filter){state.filter=b.dataset.filter;renderPage();return;}if(b.dataset.request){openRequest(Number(b.dataset.request));return;}if(b.dataset.course){await openCourse(Number(b.dataset.course));return;}if(b.dataset.assign){openAssign(Number(b.dataset.assign));return;}if(b.dataset.document){const d=state.documents.find(x=>x.id===Number(b.dataset.document));if(d)modal(d.title,`<span class="pill neutral">Учебный источник · ${d.audience==='all'?'все роли':esc(roles[d.audience])}</span><p class="kb-body section-gap">${esc(d.body)}</p>`);return;}if(b.dataset.question){await ask(b.dataset.question);return;}switch(b.dataset.action){case 'login-email':$('#email').value=b.dataset.email;$$('.account-chips .btn').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});$('#password').focus();break;case 'toggle-password':{const p=$('#password'),show=p.type==='password';p.type=show?'text':'password';b.setAttribute('aria-label',show?'Скрыть пароль':'Показать пароль');b.setAttribute('aria-pressed',String(show));break;}case 'command':openCommand();break;case 'theme':state.theme={auto:'light',light:'dark',dark:'auto'}[state.theme];applyTheme();shell();toast('Тема: '+themeLabel());break;case 'profile':openProfile();break;case 'close-modal':closeModal();break;case 'menu':window.JanaMobile?.toggleMenu();break;case 'logout':await api('logout',{});state.user=null;state.csrf='';renderLogin();break;case 'new-request':newRequest();break;case 'refresh':await refresh();toast('Данные обновлены');break;case 'read-notifications':await api('notifications/read',{});await refresh();toast('Все уведомления прочитаны');break;case 'lesson-done':await api('course/progress',{id:state.course.id});state.course=await api('course',{id:state.course.id});drawCourse();await load();renderPage();break;}}catch(err){if($('#modal').open)modalError(err.message);else toast(err.message);}});
document.addEventListener('keydown',e=>{const r=e.target.closest('[data-request]');if(r&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openRequest(Number(r.dataset.request));}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['login-form','request-form','action-form','quiz-form','chat-form','assign-form'].includes(f.id))return;e.preventDefault();const fd=new FormData(f),submit=e.submitter;try{if(f.id==='chat-form'){const q=String(fd.get('question')).trim();if(q)await ask(q);return;}if(submit){submit.disabled=true;submit.classList.add('is-loading');submit.setAttribute('aria-busy','true');}if(f.id==='login-form'){const a=await api('login',{email:fd.get('email'),password:fd.get('password')});state.user=a.user;state.csrf=a.csrf;state.page='home';history.replaceState({jana:'home'},'','#home');await load();shell();}else if(f.id==='request-form'){const made=await api('request',Object.fromEntries(fd));sessionStorage.removeItem(draftKey());$('#modal').close();state.page='requests';history.replaceState({jana:'requests'},'','#requests');state.filter='all';await refresh();openRequest(made.request.id);toast('Заявка отправлена. Следующий шаг — решение руководителя.');}else if(f.id==='action-form'){await api('request/action',{id:Number(f.dataset.id),action:submit.value,comment:fd.get('comment')});$('#modal').close();await refresh();toast('Решение сохранено. Сотруднику отправлено уведомление.');}else if(f.id==='quiz-form'){const id=state.course.id;const a=await api('course/submit',{id,answers:state.course.questions.map((q,i)=>Number(fd.get('q'+i)))});state.course=await api('course',{id});drawCourse(a);await load();renderPage();}else if(f.id==='assign-form'){await api('course/assign',{user_id:Number(f.dataset.user),course_id:Number(fd.get('course_id'))});$('#modal').close();toast('Курс назначен. Уведомление отправлено.');}}catch(err){if(f.id==='login-form'){const el=$('#login-error');el.textContent=err.message;el.classList.remove('hidden');}else modalError(err.message);}finally{if(submit){submit.disabled=false;submit.classList.remove('is-loading');submit.removeAttribute('aria-busy');}}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
// UX layer: local search, keyboard navigation, real request feedback and reduced-motion support.
function animateProgress(root){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(const bar of $$('.progress',root)){const fill=$('.progress-fill',bar);if(fill)fill.animate([{transform:'scaleX(0)'},{transform:'scaleX(1)'}],{duration:650,easing:'cubic-bezier(.22,1,.36,1)'});}}
async function navigate(page,fromHistory=false){if(state.navigating||!navigation().some(n=>n[0]===page))return;if($('#modal').open&&!closeModal())return;state.navigating=true;$('#navigation-progress')?.classList.add('active');document.body.setAttribute('aria-busy','true');try{await load();state.page=page;state.filter='all';if(!fromHistory)history.pushState({jana:page},'', '#'+page);shell();$('#content h1')?.setAttribute('tabindex','-1');$('#content h1')?.focus({preventScroll:true});}catch(e){toast(e.message);}finally{state.navigating=false;document.body.removeAttribute('aria-busy');$('#navigation-progress')?.classList.remove('active');}}
function requestStepper(r){const steps=[['submitted','Отправлено'],['approved','Руководитель'],['completed','HR']];return `<div class="request-stepper" aria-label="Маршрут заявки">${steps.map(([k,t],i)=>`<div class="stepper-item ${r.history.some(h=>h.status===k)?'done':''}"><span>${r.history.some(h=>h.status===k)?icon('check'):i+1}</span><strong>${t}</strong></div>`).join('')}</div>${r.status==='rejected'?'<p class="small rejection-caption">Заявка отклонена. Причина сохранена ниже в истории.</p>':''}`;}
function openProfile(){const u=state.user;modal('Мой профиль',`<div class="profile-top"><div class="avatar">${esc(initials(u.name))}</div><div><h3>${esc(u.name)}</h3><span class="small muted">${esc(roles[u.role])}</span></div></div><div class="details">${[['Компания',u.company],['Должность',u.position],['Подразделение',u.department],['Руководитель',u.manager_name],['Дата приёма',date(u.hire_date)],['Остаток отпуска',u.vacation_days+' дня · mock']].map(([k,v])=>`<div><span class="field-key">${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div><div class="info-strip">${icon('lock')} Кадровые данные доступны только для чтения.</div>`);}
function searchEntries(){const sections=navigation().map(([page,i,title])=>({kind:'page',id:page,title,subtitle:'Раздел платформы',icon:i}));const requests=state.requests.map(r=>({kind:'request',id:r.id,title:'Отпуск №'+r.id,subtitle:r.name+' · '+labels[r.status]+' · '+range(r),icon:'file'}));const courses=state.courses.filter(c=>c.lesson_done!==null).map(c=>({kind:'course',id:c.id,title:c.title,subtitle:'Назначенный курс · Jana Academy',icon:'book'}));const docs=state.documents.map(d=>({kind:'document',id:d.id,title:d.title,subtitle:'Учебная база знаний',icon:'file'}));return [...sections,...requests,...courses,...docs];}
function commandResults(query=''){const q=query.toLocaleLowerCase('ru').trim();const found=searchEntries().filter(e=>!q||(e.title+' '+e.subtitle).toLocaleLowerCase('ru').includes(q)).slice(0,12);return found.length?found.map(e=>`<button class="command-result" data-search-kind="${e.kind}" data-search-id="${esc(e.id)}"><span class="row-icon">${icon(e.icon)}</span><span class="grow"><strong>${esc(e.title)}</strong><small>${esc(e.subtitle)}</small></span>${icon('arrow')}</button>`).join(''):empty('Ничего не найдено','Попробуй «отпуск», «курс» или номер заявки.');}
function openCommand(){state.search='';modal('Быстрый переход',`<div class="command-input-wrap">${icon('search')}<label for="global-search" class="sr-only">Поиск по разделам и доступным данным</label><input id="global-search" type="search" placeholder="Раздел, заявка или учебный документ…" autocomplete="off"></div><p class="small muted command-caption">Поиск только по данным, доступным твоей роли · Esc — закрыть</p><div id="command-results">${commandResults()}</div>`);$('#global-search').focus();}
function updateLeavePreview(){const start=$('#start'),end=$('#end'),preview=$('#leave-preview');if(!start||!end||!preview)return;end.min=start.value||start.min;const n=Math.round((new Date(end.value)-new Date(start.value))/86400000)+1;let title='Выбери даты отпуска',text='Рассчитаем календарные дни перед отправкой.',invalid=false;if(start.value&&end.value){if(!Number.isFinite(n)||n<=0){title='Проверь даты';text='Дата окончания должна быть не раньше начала.';invalid=true;}else if(n>state.user.vacation_days){title=calendarDays(n);text='Больше тестового остатка ('+state.user.vacation_days+' дня). Выбери меньший период.';invalid=true;}else{title=calendarDays(n);text=shortDate(start.value)+' — '+shortDate(end.value)+'. Отправка заявки не означает согласование.';}}preview.classList.toggle('invalid',invalid);preview.innerHTML=`<div class="leave-preview-icon">${icon(invalid?'info':'calendar')}</div><div><strong>${esc(title)}</strong><p>${esc(text)}</p></div>`;}
document.addEventListener('input',e=>{if(e.target.id==='global-search'){$('#command-results').innerHTML=commandResults(e.target.value);}if(e.target.id==='start'||e.target.id==='end')updateLeavePreview();});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-search-kind]');if(!b)return;$('#modal').close();try{switch(b.dataset.searchKind){case 'page':await navigate(b.dataset.searchId);break;case 'request':openRequest(Number(b.dataset.searchId));break;case 'course':await openCourse(Number(b.dataset.searchId));break;case 'document':{const d=state.documents.find(d=>d.id===Number(b.dataset.searchId));if(d)modal(d.title,`<span class="pill neutral">Учебный источник</span><p class="kb-body section-gap">${esc(d.body)}</p>`);break;}}}catch(e){toast(e.message);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal').open){e.preventDefault();closeModal();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&state.user){e.preventDefault();openCommand();}if(e.key==='Escape'&&$('.sidebar.open')){window.JanaMobile?.closeMenu();}if(e.key==='ArrowDown'&&e.target.id==='global-search'){e.preventDefault();$('#command-results .command-result')?.focus();}else if(e.target.matches('.command-result')&&['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const all=$$('.command-result'),i=all.indexOf(e.target);all[(i+(e.key==='ArrowDown'?1:-1)+all.length)%all.length]?.focus();}});
window.addEventListener('popstate',()=>{if(state.user)navigate(location.hash.slice(1)||'home',true);});

(async()=>{try{const me=await api('me');state.user=me.user;state.csrf=me.csrf;await load();const target=location.hash.slice(1).split('/')[0];if(navigation().some(n=>n[0]===target))state.page=target;shell();}catch(e){renderLogin();}})();

// 0.3: short polling is deliberate: works through HTTPS proxies and Quick Tunnels.
let syncTimer=null,syncBusy=false,lastSync=0,syncFailures=0;
function localize(){window.JanaI18n?.apply();}
function stopSync(){clearTimeout(syncTimer);syncTimer=null;}
function startSync(delay=1000){if(!syncTimer&&!document.hidden)syncTimer=setTimeout(syncTick,delay);}
function showConnection(ok){const el=$('#sync-status'),banner=$('#connection-banner');if(el){el.textContent=ok?'Обновление каждые 3 секунды':'Связь потеряна';el.classList.toggle('sync-error',!ok);}if(banner){banner.classList.toggle('hidden',ok);banner.textContent='Нет связи с сервером. Данные могут быть устаревшими. Действия не будут отправлены без соединения.';}localize();}
function refreshCounters(){const unread=state.notifications.filter(n=>!n.is_read).length;for(const b of $$('[data-page=notifications]')){let badge=$('.count',b);if(badge)badge.remove();if(unread&&b.closest('.nav'))b.insertAdjacentHTML('beforeend',`<span class="count">${unread}</span>`);}const trigger=$('.notification-trigger');if(trigger){trigger.setAttribute('aria-label','Уведомления: '+unread);$('.notification-dot',trigger)?.remove();if(unread)trigger.insertAdjacentHTML('beforeend','<i class="notification-dot"></i>');}}
async function syncTick(){syncTimer=null;if(!state.user)return;if(syncBusy||state.navigating||document.hidden){syncTimer=setTimeout(syncTick,3000);return;}syncBusy=true;const uid=state.user.id;try{const snapshot=await api('snapshot');if(!state.user||state.user.id!==uid)return;const changed=snapshot.revision!==state.revision;const oldCount=state.notifications.length;const oldKnowledge=JSON.stringify(state.extra?.knowledge_revision);applySnapshot(snapshot);if(oldKnowledge!==JSON.stringify(state.extra?.knowledge_revision)){state.documents=(await api('knowledge')).documents;if(state.messages.length&&!state.busy){state.messages=[];state.threadId=null;if(state.page==='assistant'&&!state.busy)renderPage();}}lastSync=Date.now();syncFailures=0;showConnection(true);refreshCounters();if(changed){const dialog=$('#modal'),updated=snapshot.requests.find(r=>r.id===Number(dialog.dataset.requestId));if(dialog.open&&updated&&updated.status!==dialog.dataset.readStatus&&!$('#action-form')){const y=dialog.scrollTop;openRequest(updated.id);dialog.scrollTop=y;}if(state.notifications.length>oldCount)toast('Есть обновления заявок или обучения');const focused=document.activeElement;const editing=focused?.matches('input,textarea,select')||$('#modal').open;if(!editing&&!state.busy&&state.page!=='assistant'){const y=scrollY;renderPage();scrollTo(0,y);}else if($('#action-form')&&snapshot.requests.find(r=>r.id===Number($('#action-form').dataset.id))?.status!==$('#action-form').dataset.status){if(!$('#stale-warning'))$('.modal-body').insertAdjacentHTML('afterbegin','<div id="stale-warning" class="info-strip">Статус изменился. Закрой и открой заявку перед решением.</div>');}}}catch(e){syncFailures++;showConnection(false);}finally{syncBusy=false;if(state.user&&!document.hidden)syncTimer=setTimeout(syncTick,Math.min(15000,3000*Math.max(1,syncFailures)));}}
window.addEventListener('online',()=>{stopSync();startSync(0);});window.addEventListener('offline',()=>{stopSync();showConnection(false);});document.addEventListener('visibilitychange',()=>{stopSync();if(!document.hidden){window.JanaMobile?.pendingSync();startSync(0);}});window.addEventListener('pageshow',e=>{if(e.persisted){stopSync();window.JanaMobile?.pendingSync();startSync(0);}});
const originalOpenRequest=openRequest;openRequest=function(id){originalOpenRequest(id);$('#modal').dataset.requestId=id;$('#modal').dataset.readStatus=state.requests.find(r=>r.id===id)?.status;const f=$('#action-form');if(f)f.dataset.status=state.requests.find(r=>r.id===id)?.status;};
function draftKey(){return 'jana-draft-'+state.user?.id;}
function saveDraft(){const f=$('#request-form');if(!f||!state.user)return;const d=Object.fromEntries(new FormData(f));sessionStorage.setItem(draftKey(),JSON.stringify(d));}
function hasDraftFields(){return !!($('#start')?.value||$('#end')?.value||$('#comment')?.value.trim());}
function closeModal(){if($('#request-form')&&hasDraftFields()){if(!confirm(window.JanaI18n?.lang==='kk'?'Жабу керек пе? Нобай осы қойындыда сақталады.':'Закрыть форму? Черновик сохранится в этой вкладке.'))return false;saveDraft();}$('#modal').close();return true;}
$('#modal').addEventListener('cancel',e=>{if($('#request-form')&&hasDraftFields()){e.preventDefault();closeModal();}});
window.addEventListener('beforeunload',e=>{if($('#request-form')&&hasDraftFields()){saveDraft();e.preventDefault();e.returnValue='';}});
document.addEventListener('input',e=>{if(e.target.closest('#request-form'))saveDraft();});
const baseNewRequest=newRequest;newRequest=function(){baseNewRequest();try{const d=JSON.parse(sessionStorage.getItem(draftKey())||'null');if(d){for(const name of ['start','end','comment']){const input=$('#request-form [name="'+name+'"]');if(input)input.value=d[name]||'';}updateLeavePreview();}}catch(e){};};
function tutorialVideo(){return `<section class="tutorial"><div><span class="eyebrow">Быстрый старт</span><h3>JanaМен за 75 секунд</h3><p class="small muted">Видео без озвучки, с текстовыми подписями. Ниже есть текстовая инструкция.</p></div><video controls playsinline preload="none" poster="/assets/tutorial-poster.png" aria-label="Как пользоваться JanaМен"><source src="/assets/tutorial.mp4" type="video/mp4"><track kind="subtitles" srclang="ru" label="Русский" src="/assets/tutorial-ru.vtt">Браузер не поддерживает видео.</video><details><summary>Текстовая инструкция</summary><ol><li>Войди под своей ролью. Открой профиль и проверь данные.</li><li>В «Мои заявки» создай отпуск: даты, комментарий, отправка.</li><li>Руководитель увидит заявку автоматически. HR обработает её после согласования.</li><li>Следи за историей и уведомлениями. Обычно обновление занимает до 3 секунд в активной вкладке.</li><li>В Academy изучи материал и пройди тест. Результат сохраняется.</li><li>В Workspace создай общее пространство, задачу и загрузи документ. Видимость определяется участниками.</li><li>В «Сервисы» отправь обращение HR, IT или офису. Ответственный ведёт его до решения.</li><li>Спроси AI Jana и открой источник. Без ключа работает поиск; при отсутствии ответа обратись в HR.</li></ol></details></section>`;}
function openGuide(){modal('Как пользоваться JanaМен',tutorialVideo()+`<div class="info-strip">Только учебные данные. Видео показывает работу прототипа, а не кадровый регламент компании.</div>`);}
const originalHome=homePage;homePage=function(){const pending=state.requests.filter(r=>r.user_id!==state.user.id&&((state.user.role==='manager'&&r.status==='submitted')||(state.user.role==='hr'&&r.status==='approved'))).length;return (state.user.role!=='employee'?`<button class="action-inbox" data-page="team"><span>${icon('users')} Требуют твоего решения</span><strong>${pending}</strong>${icon('arrow')}</button>`:'')+originalHome()+`<section class="onboarding-card section-gap"><div><span class="eyebrow">Освойся за минуту</span><h2>Все возможности — без поиска по меню</h2><p>Посмотри короткое видео или установи кабинет на телефон.</p></div><div class="hero-actions"><button class="btn primary" data-action="guide">Смотреть инструкцию ${icon('arrow')}</button><button class="btn" data-action="install">Установить на телефон</button></div></section>`;};
const originalAcademy=academyPage;academyPage=function(){return `<div class="academy-guide"><button class="btn" data-action="guide">Видео: как пользоваться JanaМен</button><button class="btn ghost" data-action="install">Установить приложение</button></div>`+originalAcademy();};
const originalTeam=teamPage;teamPage=function(){const old=state.requests;const q=state.teamSearch.toLowerCase();let count=old.filter(r=>r.user_id!==state.user.id&&r.status===(state.user.role==='hr'?'approved':'submitted')).length;state.requests=old.filter(r=>(state.teamFilter==='all'||(state.teamFilter==='action'?r.status===(state.user.role==='hr'?'approved':'submitted'):r.status===state.teamFilter))&&(!q||('№'+r.id+' '+r.name+' '+r.start_date).toLowerCase().includes(q)));let html=originalTeam();state.requests=old;const controls=`<div class="queue-tools"><div class="filters">${[['action','Требуют действия ('+count+')'],['all','Все'],['submitted','На согласовании'],['approved','Согласованы'],['completed','Обработаны'],['rejected','Отклонены'],['withdrawn','Отозваны']].map(([v,t])=>`<button class="filter ${state.teamFilter===v?'active':''}" data-queue="${v}">${t}</button>`).join('')}</div><label class="queue-search">Поиск заявки<input id="queue-search" type="text" value="${esc(state.teamSearch)}" placeholder="Имя или номер заявки"></label></div>`;return html.replace('<section class="card">',controls+'<section class="card">');};
const originalRenderMessages=renderMessages;renderMessages=function(){return state.messages.map((m,i)=>`<article class="message ${m.role==='user'?'user':''}"><span class="small muted">${m.role==='user'?'Ты':['groq','anymodel','gemini'].includes(m.mode)?(m.mode==='gemini'?'Jana · Gemini':'Jana · ИИ'):m.mode==='account'?'Jana · твой аккаунт':m.mode==='help'?'Jana · помощь':m.mode==='error'?'Jana · ошибка подключения':m.mode==='no_answer'?'Jana · нет источника':'Jana · учебная база'}</span><p class="message-text">${esc(m.text)}</p>${m.notice?`<p class="small muted">${esc(m.notice)}</p>`:''}${m.claims?.length?`<details class="evidence"><summary>Проверить цитаты</summary>${m.claims.map(c=>`<blockquote>${esc(c.quote)}<button class="btn ghost" data-document="${c.source_id}">Источник ${c.source_id}</button></blockquote>`).join('')}</details>`:''}${m.sources?.length?`<div class="small muted">Справочный контекст${m.sources.length>3?` · ещё ${m.sources.length-3} инструкций`:""}</div><div class="sources">${m.sources.slice(0,3).map(d=>`<button class="btn" data-document="${d.id}">${icon('file')}${esc(d.title)}</button>`).join('')}</div>`:''}${m.actions?.length?`<div class="hero-actions">${m.actions.map(a=>`<button class="btn" ${a.request_id?`data-request="${a.request_id}"`:a.page?`data-page="${esc(a.page)}"`:`data-action="${esc(a.action)}"`}>${esc(a.label)} ${icon('arrow')}</button>`).join('')}</div>`:''}${m.role!=='user'&&m.mode!=='no_answer'?`<div class="feedback-row"><span class="small muted">Ответ помог?</span><button class="btn ghost" data-feedback="${i}" data-helpful="true" ${m.feedback?'disabled':''}>Да</button><button class="btn ghost" data-feedback="${i}" data-helpful="false" ${m.feedback?'disabled':''}>Нет</button>${m.feedback?'<span class="small muted">Спасибо за отзыв</span>':''}</div>`:''}</article>`).join('');};
let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
async function openInstall(){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;return;}modal('JanaМен на телефоне',`<div class="install-steps"><h3>iPhone / iPad</h3><p>Открой HTTPS-адрес в Safari → «Поделиться» → «На экран “Домой”».</p><h3>Android</h3><p>Открой HTTPS-адрес в Chrome → меню → «Установить приложение» или «Добавить на главный экран».</p><div class="info-strip">Все устройства используют один адрес сервера. Компьютер с сервером должен оставаться включённым, если используешь туннель.</div><p class="small muted">Это PWA, не приложение из магазина. Системные push-уведомления в этой версии не подключены: обновления приходят при открытом приложении.</p></div>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.queue){state.teamFilter=b.dataset.queue;renderPage();}if(b.dataset.action==='guide')openGuide();if(b.dataset.action==='install')await openInstall();if(b.dataset.action==='language'){window.JanaI18n.toggle();if(state.user)shell();else renderLogin();}if(b.dataset.feedback){const m=state.messages[Number(b.dataset.feedback)];if(!m||m.feedback)return;await api('assistant/feedback',{source_ids:(m.sources||[]).map(d=>d.id),helpful:b.dataset.helpful==='true'});m.feedback=true;renderPage();}}catch(e){toast(e.message);}});
document.addEventListener('input',e=>{if(e.target.id==='queue-search'){const pos=e.target.selectionStart;state.teamSearch=e.target.value;renderPage();const input=$('#queue-search');input.focus();input.setSelectionRange?.(pos,pos);}});
// Mobile module registers the worker and offers safe, explicit updates.
